<?php
if (!defined('ABSPATH')) exit;

final class MathBinder_Math_Notes {
    const META_KEY = 'mb_structured_math_notes_v1';

    public static function register() {
        add_action('wp_enqueue_scripts', [__CLASS__, 'assets']);
        add_action('template_redirect', [__CLASS__, 'route_canvas_assignment_post'], 2);
        add_action('admin_post_mb_student_save_math_note', [__CLASS__, 'save_note']);
        add_action('admin_post_mb_student_submit_math_note', [__CLASS__, 'submit_note']);
        add_action('admin_post_mb_student_delete_math_note', [__CLASS__, 'delete_note']);
        add_action('admin_post_mb_canvas_save_assignment', [__CLASS__, 'save_canvas_assignment']);
        add_action('admin_post_mb_teacher_review_math_note', [__CLASS__, 'review_note']);
        add_action('admin_post_mb_teacher_canvas_note_preview', [__CLASS__, 'canvas_preview']);
    }
    public static function route_canvas_assignment_post() {
        if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && isset($_POST['mb_canvas_assignment_submit'])) self::save_canvas_assignment();
    }
    public static function assets() { if (is_page(['student-dashboard','teacher-dashboard','teacher-student-progress']) || is_singular(MathBinder_Core::CPT)) { wp_enqueue_style('mathbinder-math-notes', plugins_url('assets/math-notes.css', __FILE__), [], MathBinder_Core::VERSION); wp_enqueue_script('mathbinder-math-notes', plugins_url('assets/math-notes.js', __FILE__), [], MathBinder_Core::VERSION, true); } }
    private static function go($anchor,$notice,array $args=[]) { $url=wp_get_referer()?:home_url('/'); wp_safe_redirect(add_query_arg(array_merge(['notes_notice'=>$notice],$args),remove_query_arg(['notes_notice','note_id'],$url)).$anchor); exit; }
    private static function go_canvas($lesson_id,$session,$notice,$note_id='') {
        $url=get_permalink(absint($lesson_id));
        $args=['notes_notice'=>sanitize_key($notice),'mb_canvas_assignment_session'=>(string)$session];
        if($note_id!=='')$args['note_id']=sanitize_key($note_id);
        wp_safe_redirect(add_query_arg($args,$url).'#workbook');
        exit;
    }
    public static function all($student_id) { $notes=get_user_meta(absint($student_id),self::META_KEY,true); return is_array($notes)?$notes:[]; }
    private static function put($student_id,array $note) { $notes=self::all($student_id); $notes[$note['id']]=$note; if(count($notes)>250)$notes=array_slice($notes,-250,null,true); update_user_meta(absint($student_id),self::META_KEY,$notes); }
    private static function classes($student_id) { global $wpdb; return $wpdb->get_results($wpdb->prepare("SELECT c.id,c.name,c.section_name FROM {$wpdb->prefix}mb_enrollments e JOIN {$wpdb->prefix}mb_classes c ON c.id=e.class_id AND c.status='active' WHERE e.user_id=%d AND e.role_key='student' AND e.status='active' ORDER BY c.name",absint($student_id)),ARRAY_A)?:[]; }
    private static function active_class($student_id,$class_id) { foreach(self::classes($student_id) as $class)if((int)$class['id']===absint($class_id))return $class; return null; }
    private static function ensure_canvas_enrollment($student_id,$class_id) {
        global $wpdb;
        $student_id=absint($student_id); $class_id=absint($class_id);
        if(!$student_id||!$class_id)return false;
        $class=$wpdb->get_row($wpdb->prepare("SELECT id FROM {$wpdb->prefix}mb_classes WHERE id=%d AND status='active'",$class_id),ARRAY_A);
        if(!$class)return false;
        $existing=$wpdb->get_row($wpdb->prepare("SELECT id,status FROM {$wpdb->prefix}mb_enrollments WHERE class_id=%d AND user_id=%d AND role_key='student' ORDER BY id DESC LIMIT 1",$class_id,$student_id),ARRAY_A);
        $now=current_time('mysql',true);
        if($existing){
            if(($existing['status']??'')!=='active')$wpdb->update($wpdb->prefix.'mb_enrollments',['status'=>'active','source'=>'canvas_lti','updated_at'=>$now],['id'=>absint($existing['id'])],['%s','%s','%s'],['%d']);
        }else{
            $user=get_userdata($student_id);
            $wpdb->insert($wpdb->prefix.'mb_enrollments',['class_id'=>$class_id,'user_id'=>$student_id,'invited_email'=>$user?(string)$user->user_email:'','role_key'=>'student','status'=>'active','source'=>'canvas_lti','approved_by'=>0,'created_at'=>$now,'updated_at'=>$now],['%d','%d','%s','%s','%s','%s','%d','%s','%s']);
        }
        return (bool)self::active_class($student_id,$class_id);
    }
    private static function field($name,$limit=500) { return mb_substr(sanitize_text_field(wp_unslash($_POST[$name]??'')),0,$limit); }

    public static function save_note() {
        if(!is_user_logged_in())wp_die('Student access required.','',['response'=>403]); check_admin_referer('mb_student_save_math_note','mb_math_note_nonce');
        $student_id=get_current_user_id(); $notes=self::all($student_id); $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $old=$id&&isset($notes[$id])?$notes[$id]:null;
        if($old&&!in_array($old['status']??'draft',['draft','revision_requested'],true))self::go('#my-math-notes','locked');
        $title=self::field('note_title',160); $label=self::field('organization_label',200); $content=wp_kses_post(wp_unslash($_POST['note_content']??''));
        if($title===''||$label===''||trim(wp_strip_all_tags($content))==='')self::go('#my-math-notes','invalid');
        if(!$id)$id='note_'.wp_generate_uuid4(); $now=current_time('mysql',true);
        $note=wp_parse_args((array)$old,['id'=>$id,'student_id'=>$student_id,'created_at'=>$now,'status'=>'draft','version'=>0,'submitted_snapshot'=>[],'submission_history'=>[],'review'=>[]]);
        $type=self::field('organization_type',20); $color=self::field('note_color',20);
        $allowed_types=['topic','unit','standard','ican','week','vocabulary','chapter','custom'];
        $drawing=wp_unslash($_POST['drawing_data']??''); if(!preg_match('#^data:image/(png|webp);base64,[A-Za-z0-9+/=]+$#',$drawing)||strlen($drawing)>1500000)$drawing='';
        $note=array_merge($note,['title'=>$title,'organization_type'=>in_array($type,$allowed_types,true)?$type:'topic','organization_label'=>$label,'subcategory_type'=>self::field('subcategory_type',100),'subcategory_label'=>self::field('subcategory_label',200),'standard'=>self::field('standard',200),'ican'=>self::field('ican',300),'tags'=>array_values(array_filter(array_map('sanitize_text_field',explode(',',self::field('tags',500))))),'content'=>$content,'drawing_data'=>$drawing,'class_id'=>absint($_POST['class_id']??0),'canvas_assignment'=>self::field('canvas_assignment',200),'color'=>in_array($color,['teal','purple','blue','gold'],true)?$color:'teal','status'=>($old&&($old['status']??'')==='revision_requested')?'revision_requested':'draft','updated_at'=>$now]);
        self::put($student_id,$note); MathBinder_Audit_Log::record('save_math_note','user',$student_id,['note_id'=>$id,'private'=>true]); self::go('#my-math-notes','saved',['note_id'=>$id]);
    }
    public static function submit_note() {
        if(!is_user_logged_in())wp_die('Student access required.','',['response'=>403]); check_admin_referer('mb_student_submit_math_note','mb_math_note_submit_nonce');
        $student_id=get_current_user_id(); $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $notes=self::all($student_id); $note=$notes[$id]??null;
        if(!$note||!in_array($note['status']??'', ['draft','revision_requested'],true)||!self::active_class($student_id,$note['class_id']??0))self::go('#my-math-notes','submit_invalid');
        $version=absint($note['version']??0)+1; $now=current_time('mysql',true); $snapshot=array_intersect_key($note,array_flip(['id','student_id','title','organization_type','organization_label','subcategory_type','subcategory_label','standard','ican','tags','content','drawing_data','class_id','canvas_assignment','color'])); $snapshot['version']=$version; $snapshot['submitted_at']=$now;
        $history=is_array($note['submission_history']??null)?$note['submission_history']:[];$history[(string)$version]=$snapshot;if(count($history)>20)$history=array_slice($history,-20,null,true);$note['version']=$version; $note['submitted_snapshot']=$snapshot; $note['submission_history']=$history; $note['status']='submitted'; $note['review']=[]; $note['updated_at']=$now; self::put($student_id,$note); MathBinder_Audit_Log::record('submit_math_note','user',$student_id,['note_id'=>$id,'class_id'=>absint($note['class_id']),'version'=>$version]); self::go('#my-math-notes','submitted',['note_id'=>$id]);
    }
    public static function delete_note() {
        if(!is_user_logged_in())wp_die('Student access required.','',['response'=>403]); check_admin_referer('mb_student_delete_math_note','mb_math_note_delete_nonce');
        $student_id=get_current_user_id(); $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $notes=self::all($student_id); $note=$notes[$id]??null;
        if(!$note)self::go('#my-math-notes','delete_invalid');
        $preserve=!empty($note['submitted_snapshot'])||!empty($note['submission_history']);
        if($preserve){$note['student_deleted']=true;$note['student_deleted_at']=current_time('mysql',true);$notes[$id]=$note;}else{unset($notes[$id]);}
        update_user_meta($student_id,self::META_KEY,$notes);
        MathBinder_Audit_Log::record('delete_math_note','user',$student_id,['note_id'=>$id,'submitted_snapshot_preserved'=>$preserve]);
        self::go('#my-math-notes','deleted');
    }

    public static function save_canvas_assignment() {
        $lesson_id=absint($_POST['lesson_id']??0);
        $assignment_session=sanitize_text_field(wp_unslash($_POST['mb_canvas_assignment_session']??''));
        $launch=MathBinder_Canvas_Deep_Linking::current_resource_launch($lesson_id);
        if(!$launch){
            $launch=MathBinder_Canvas_Deep_Linking::assignment_form_launch($assignment_session,$lesson_id);
        }
        if(!$launch||empty($launch['user_id']))wp_die('Canvas student session was not received. Reopen this assignment from Canvas. (MB-CANVAS-SESSION)','',['response'=>403]);
        $student_id=absint($launch['user_id']); wp_set_current_user($student_id);
        if(!$student_id||!get_userdata($student_id))wp_die('The mapped Canvas student account is unavailable. Ask your teacher to review the approved user mapping. (MB-CANVAS-USER)','',['response'=>403]);
        check_admin_referer('mb_canvas_save_assignment','mb_canvas_assignment_nonce');
        if(!MathBinder_Canvas_Deep_Linking::resource_launch_is_student($launch))wp_die('Canvas did not identify this launch as a student assignment. Open the assignment using Canvas Student View. (MB-CANVAS-ROLE)','',['response'=>403]);
        $class_id=absint($launch['class_id']??0);
        if(!$class_id)wp_die('The Canvas course is not mapped to a MathBinder class. Ask the administrator to review the approved course mapping. (MB-CANVAS-CLASS)','',['response'=>403]);
        if(!self::ensure_canvas_enrollment($student_id,$class_id))wp_die('The mapped Canvas student could not be enrolled in the mapped MathBinder class. (MB-CANVAS-ENROLLMENT)','',['response'=>403]);
        $lesson=get_post($lesson_id); if(!$lesson||$lesson->post_type!==MathBinder_Core::CPT||$lesson->post_status!=='publish')wp_die('Lesson unavailable.','',['response'=>404]);
        $content=wp_kses_post(wp_unslash($_POST['note_content']??'')); $drawing=wp_unslash($_POST['drawing_data']??'');
        if(!preg_match('#^data:image/(png|webp);base64,[A-Za-z0-9+/=]+$#',$drawing)||strlen($drawing)>1500000)$drawing='';
        if($assignment_session==='')$assignment_session=MathBinder_Canvas_Deep_Linking::assignment_form_token($launch);
        if(trim(wp_strip_all_tags($content))===''&&$drawing==='')self::go_canvas($lesson_id,$assignment_session,'invalid');
        $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $notes=self::all($student_id); $old=$id&&isset($notes[$id])?$notes[$id]:null;
        if($old&&!in_array($old['status']??'draft',['draft','revision_requested'],true))$old=null;
        if(!$old)$id='note_'.wp_generate_uuid4(); $now=current_time('mysql',true); $term=wp_get_post_terms($lesson_id,MathBinder_Core::TAX,['fields'=>'names']); $label=!is_wp_error($term)&&$term?reset($term):'Canvas assignment';
        $note=wp_parse_args((array)$old,['id'=>$id,'student_id'=>$student_id,'created_at'=>$now,'version'=>0,'submitted_snapshot'=>[],'submission_history'=>[],'review'=>[]]);
        $note=array_merge($note,['title'=>get_the_title($lesson),'organization_type'=>'topic','organization_label'=>$label,'subcategory_type'=>'Canvas lesson','subcategory_label'=>get_the_title($lesson),'standard'=>'','ican'=>'','tags'=>['Canvas'],'content'=>$content,'drawing_data'=>$drawing,'class_id'=>$class_id,'canvas_assignment'=>'lesson:'.$lesson_id,'color'=>'purple','status'=>'draft','updated_at'=>$now]);
        $submit=sanitize_key(wp_unslash($_POST['assignment_action']??''))==='submit';
        if($submit){$version=absint($note['version']??0)+1;$snapshot=array_intersect_key($note,array_flip(['id','student_id','title','organization_type','organization_label','subcategory_type','subcategory_label','standard','ican','tags','content','drawing_data','class_id','canvas_assignment','color']));$snapshot['version']=$version;$snapshot['submitted_at']=$now;$history=is_array($note['submission_history']??null)?$note['submission_history']:[];$history[(string)$version]=$snapshot;$note['version']=$version;$note['submitted_snapshot']=$snapshot;$note['submission_history']=$history;$note['status']='submitted';$note['review']=[];}
        self::put($student_id,$note); $notice=$submit?'canvas_submitted':'saved';
        if($submit){$result=MathBinder_Canvas_Integration::adapter()->submit_activity(['scores_url'=>$launch['scores_url']??'','user_id'=>$launch['external_user_id']??'','comment'=>'MathBinder assignment snapshot v'.$version.' submitted for teacher review.']);if(is_wp_error($result)){$notice='canvas_submit_failed';$note['status']='draft';$note['submitted_snapshot']=[];self::put($student_id,$note);}MathBinder_Audit_Log::record(is_wp_error($result)?'failed':'sent','canvas_assignment_submission',$id,['class_id'=>$class_id,'lesson_id'=>$lesson_id,'snapshot_version'=>$version]);}
        MathBinder_Audit_Log::record($submit?'submit_canvas_assignment':'save_canvas_assignment','user',$student_id,['note_id'=>$id,'class_id'=>$class_id,'lesson_id'=>$lesson_id]); self::go_canvas($lesson_id,$assignment_session,$notice,$id);
    }

    public static function canvas_lesson_section($lesson_id,$class_id) {
        $lesson_id=absint($lesson_id); $class_id=absint($class_id);
        $launch=MathBinder_Canvas_Deep_Linking::current_resource_launch($lesson_id); $launch_token=(string)($launch['resource_token']??'');
        $assignment_session=(string)($launch['assignment_session']??MathBinder_Canvas_Deep_Linking::assignment_form_token($launch));
        $student_id=absint($launch['user_id']??get_current_user_id());
        $matching=array_values(array_filter(self::all($student_id),function($note)use($lesson_id,$class_id){return empty($note['student_deleted'])&&absint($note['class_id']??0)===$class_id&&($note['canvas_assignment']??'')==='lesson:'.$lesson_id;}));
        $note=$matching?end($matching):[]; $editable=$note&&in_array($note['status']??'',['draft','revision_requested'],true)?$note:[]; $notice=sanitize_key(wp_unslash($_GET['notes_notice']??''));
        $form_action=$launch_token!==''?add_query_arg('mb_canvas_launch',$launch_token,get_permalink($lesson_id)):get_permalink($lesson_id);
        ob_start(); ?>
        <section class="mb-canvas-assignment-work" aria-labelledby="mb-canvas-work-title">
            <div class="mb-panel-heading"><div><span class="mb-eyebrow">Canvas assignment work</span><h2 id="mb-canvas-work-title">Write, draw, save, and submit</h2></div></div>
            <p class="mb-note-privacy">Your saved work stays attached to this lesson and class. Select <strong>Submit Assignment</strong> when it is ready for your teacher.</p>
            <?php if($notice==='saved'): ?><div class="mb-note-notice is-success">Your assignment notes were saved. You can keep working or submit them.</div>
            <?php elseif($notice==='canvas_submitted'): ?><div class="mb-note-notice is-success">Assignment submitted. Canvas now shows it completed and awaiting teacher review; the locked written-and-drawn version is available to your MathBinder teacher.</div>
            <?php elseif($notice==='canvas_submit_failed'): ?><div class="mb-note-notice is-error">Your work was saved for your MathBinder teacher, but Canvas did not confirm the submission. Ask your teacher to check the Canvas connection log.</div>
            <?php elseif($notice==='invalid'): ?><div class="mb-note-notice is-error">Write a note or add a drawing before saving.</div><?php endif; ?>
            <?php if($note&&!$editable): $s=$note['submitted_snapshot']??$note; ?>
                <article class="mb-note-card is-purple"><small>Submitted · Snapshot v<?php echo absint($s['version']??1); ?></small><h3><?php echo esc_html($s['title']??get_the_title($lesson_id)); ?></h3><?php if(!empty($s['content'])):?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($s['content'])); ?></div><?php endif; ?><?php if(!empty($s['drawing_data'])):?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($s['drawing_data']); ?>" alt="Submitted math drawing"><?php endif; ?></article>
            <?php else: ?>
                <form class="mb-note-editor" data-mb-note-editor method="post" action="<?php echo esc_url($form_action); ?>">
                    <input type="hidden" name="action" value="mb_canvas_save_assignment">
                    <input type="hidden" name="mb_canvas_assignment_submit" value="1">
                    <input type="hidden" name="mb_canvas_launch" value="<?php echo esc_attr($launch_token); ?>">
                    <input type="hidden" name="mb_canvas_assignment_session" value="<?php echo esc_attr($assignment_session); ?>">
                    <input type="hidden" name="lesson_id" value="<?php echo $lesson_id; ?>">
                    <input type="hidden" name="class_id" value="<?php echo $class_id; ?>">
                    <input type="hidden" name="note_id" value="<?php echo esc_attr($editable['id']??''); ?>">
                    <?php wp_nonce_field('mb_canvas_save_assignment','mb_canvas_assignment_nonce'); ?>
                    <label>My written notes<textarea rows="9" name="note_content" data-mb-note-content placeholder="Write definitions, examples, worked problems, questions, or reminders here…"><?php echo esc_textarea(wp_strip_all_tags($editable['content']??'')); ?></textarea></label>
                    <div class="mb-drawing-workspace"><div class="mb-drawing-heading"><strong>Draw or show your work</strong><span>Pen, highlighter, eraser, undo, and clear</span></div><div class="mb-drawing-toolbar"><button type="button" data-tool="pen">Pen</button><button type="button" data-tool="highlighter">Highlighter</button><button type="button" data-tool="eraser">Eraser</button><label>Color <input type="color" value="#25364d" data-mb-draw-color></label><label>Size <input type="range" min="2" max="28" value="4" data-mb-draw-size></label><button type="button" data-tool="undo">Undo</button><button type="button" data-tool="clear">Clear</button></div><canvas width="900" height="420" data-mb-drawing aria-label="Canvas assignment drawing area"></canvas><input type="hidden" name="drawing_data" data-mb-drawing-data value="<?php echo esc_attr($editable['drawing_data']??''); ?>"></div>
                    <div class="mb-canvas-assignment-actions"><button type="submit" name="assignment_action" value="save">Save Notes</button><button class="mb-button mb-button-primary" type="submit" name="assignment_action" value="submit" onclick="return confirm('Submit this exact written and drawn version to your teacher?');">Submit Assignment</button></div>
                </form>
            <?php endif; ?>
        </section>
        <?php return ob_get_clean();
    }

