ton></div></form><?php endif; ?></section><?php return ob_get_clean();
    }
    private static function can_review($teacher_id,$student_id,$class_id) { global $wpdb; $enrolled=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}mb_enrollments WHERE class_id=%d AND user_id=%d AND role_key='student' AND status='active'",absint($class_id),absint($student_id))); return $enrolled&&MathBinder_Class_Staff::can($teacher_id,$class_id,'view_evidence')&&MathBinder_Class_Staff::can($teacher_id,$class_id,'provide_feedback'); }
    public static function can_teacher_review($teacher_id,$student_id,$class_id) { return self::can_review($teacher_id,$student_id,$class_id); }
    public static function submitted_for_student($student_id,array $class_ids) { return array_values(array_filter(self::all($student_id),function($note)use($class_ids){return !empty($note['submitted_snapshot'])&&in_array(absint($note['class_id']??0),array_map('absint',$class_ids),true)&&in_array($note['status']??'', ['submitted','feedback','revision_requested','graded'],true);})); }
    public static function review_note() {
        if(!is_user_logged_in())wp_die('Teacher access required.','',['response'=>403]); check_admin_referer('mb_teacher_review_math_note','mb_math_note_review_nonce');
        $teacher_id=get_current_user_id(); $student_id=absint($_POST['student_id']??0); $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $notes=self::all($student_id); $note=$notes[$id]??null;
        if(!$note||!self::can_review($teacher_id,$student_id,$note['class_id']??0))self::go('#submitted-math-notes','review_denied',['student'=>$student_id]);
        $decision=self::field('decision',30); $grade_type=self::field('grade_type',30); $decision=in_array($decision,['feedback','revision_requested','graded'],true)?$decision:'feedback'; $grade_type=in_array($grade_type,['points','percentage','completion','rubric'],true)?$grade_type:'points'; $user=wp_get_current_user();
        $note['status']=$decision; $note['review']=['decision'=>$decision,'feedback'=>wp_kses_post(wp_unslash($_POST['feedback']??'')),'grade_type'=>$grade_type,'score'=>floatval($_POST['score']??0),'points_possible'=>max(0,floatval($_POST['points_possible']??0)),'rubric_level'=>self::field('rubric_level',100),'teacher_id'=>$teacher_id,'teacher_name'=>$user->display_name,'reviewed_at'=>current_time('mysql',true),'snapshot_version'=>absint($note['submitted_snapshot']['version']??0)]; self::put($student_id,$note); MathBinder_Audit_Log::record('review_math_note','user',$student_id,['note_id'=>$id,'decision'=>$decision]); self::go('#submitted-math-notes','reviewed',['student'=>$student_id]);
    }
    public static function canvas_preview() {
        if(!is_user_logged_in())wp_die('Teacher access required.','',['response'=>403]); check_admin_referer('mb_teacher_canvas_note_preview','mb_canvas_note_nonce'); $teacher_id=get_current_user_id(); $student_id=absint($_POST['student_id']??0); $id=sanitize_key(wp_unslash($_POST['note_id']??'')); $all=self::all($student_id); $note=$all[$id]??null;
        if(!$note||!self::can_review($teacher_id,$student_id,$note['class_id']??0))self::go('#submitted-math-notes','canvas_denied',['student'=>$student_id]); $result=MathBinder_Canvas_Integration::prepare_note_submission($note,$student_id,$teacher_id); self::go('#submitted-math-notes',is_wp_error($result)?'canvas_failed':'canvas_prepared',['student'=>$student_id]);
    }

    private static function editor(array $note,array $classes) {
        $new=empty($note['id']); $note=wp_parse_args($note,['id'=>'','title'=>'','organization_type'=>'topic','organization_label'=>'','subcategory_type'=>'','subcategory_label'=>'','standard'=>'','ican'=>'','tags'=>[],'content'=>'','drawing_data'=>'','class_id'=>0,'canvas_assignment'=>'','color'=>'teal']); ob_start(); ?>
        <form class="mb-note-editor" data-mb-note-editor method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="mb_student_save_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_save_math_note','mb_math_note_nonce'); ?><div class="mb-note-grid"><label>Note title<input required maxlength="160" name="note_title" value="<?php echo esc_attr($note['title']); ?>"></label><label>Organize by<select name="organization_type"><?php foreach(['topic'=>'Topic','unit'=>'Unit of study','standard'=>'Standard','ican'=>'I Can statement','week'=>'Week of school','vocabulary'=>'Vocabulary','chapter'=>'Chapter','custom'=>'Custom category'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($note['organization_type'],$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>Main category label<input required maxlength="200" name="organization_label" value="<?php echo esc_attr($note['organization_label']); ?>" placeholder="Example: Week 1 or Number Operations"></label><label>Subcategory type (optional)<input maxlength="100" name="subcategory_type" value="<?php echo esc_attr($note['subcategory_type']); ?>" placeholder="Example: Vocabulary, Homework, Examples"></label><label>Subcategory label (optional)<input maxlength="200" name="subcategory_label" value="<?php echo esc_attr($note['subcategory_label']); ?>" placeholder="Example: Integer vocabulary"></label><label>Class (required only when submitting)<select name="class_id"><option value="0">Private / not assigned</option><?php foreach($classes as $class): ?><option value="<?php echo absint($class['id']); ?>" <?php selected(absint($note['class_id']),absint($class['id'])); ?>><?php echo esc_html($class['name'].($class['section_name']?' · '.$class['section_name']:'')); ?></option><?php endforeach; ?></select></label><label>California standard<input maxlength="200" name="standard" value="<?php echo esc_attr($note['standard']); ?>"></label><label>I Can statement<input maxlength="300" name="ican" value="<?php echo esc_attr($note['ican']); ?>"></label><label>Tags (comma separated)<input maxlength="500" name="tags" value="<?php echo esc_attr(implode(', ',(array)$note['tags'])); ?>"></label><label>Canvas assignment name (optional)<input maxlength="200" name="canvas_assignment" value="<?php echo esc_attr($note['canvas_assignment']); ?>"></label></div><div class="mb-note-tools"><div><strong>Math symbols</strong><div class="mb-symbol-palette" aria-label="Insert a math symbol"><?php foreach(['±','×','÷','·','−','≤','≥','≠','≈','∞','π','√','∛','²','³','°','∠','△','≅','∼','∑','∫','½','¼','¾','⅓','⅔'] as $symbol): ?><button type="button" data-mb-symbol="<?php echo esc_attr($symbol); ?>"><?php echo esc_html($symbol); ?></button><?php endforeach; ?></div></div><div class="mb-calculator-links"><strong>Calculators</strong><a href="https://www.desmos.com/scientific" target="_blank" rel="noopener noreferrer">Open Scientific Calculator</a><a href="https://www.desmos.com/calculator" target="_blank" rel="noopener noreferrer">Open Graphing Calculator</a></div></div><label>My notes<textarea required rows="8" name="note_content" data-mb-note-content><?php echo esc_textarea(wp_strip_all_tags($note['content'])); ?></textarea></label><div class="mb-drawing-workspace"><div class="mb-drawing-heading"><strong>Draw or show your work</strong><span>Pen, highlighter, eraser, undo, and clear</span></div><div class="mb-drawing-toolbar"><button type="button" data-tool="pen">Pen</button><button type="button" data-tool="highlighter">Highlighter</button><button type="button" data-tool="eraser">Eraser</button><label>Color <input type="color" value="#25364d" data-mb-draw-color></label><label>Size <input type="range" min="2" max="28" value="4" data-mb-draw-size></label><button type="button" data-tool="undo">Undo</button><button type="button" data-tool="clear">Clear</button></div><canvas width="900" height="420" data-mb-drawing aria-label="Math notes drawing canvas"></canvas><input type="hidden" name="drawing_data" data-mb-drawing-data value="<?php echo esc_attr($note['drawing_data']); ?>"></div><label>Color<select name="note_color"><?php foreach(['teal','purple','blue','gold'] as $color): ?><option value="<?php echo esc_attr($color); ?>" <?php selected($note['color'],$color); ?>><?php echo esc_html(ucfirst($color)); ?></option><?php endforeach; ?></select></label><button class="mb-button mb-button-primary" type="submit"><?php echo $new?'Save Private Draft':'Save Changes'; ?></button></form><?php return ob_get_clean();
    }
    public static function student_section() {
        $student_id=get_current_user_id(); $notes=array_reverse(array_filter(self::all($student_id),function($note){return empty($note['student_deleted']);})); $classes=self::classes($student_id); $notice=sanitize_key(wp_unslash($_GET['notes_notice']??'')); $messages=['saved'=>'Private draft saved.','submitted'=>'A locked snapshot was submitted to your teacher.','deleted'=>'The note was removed from My Math Notes. Any previously submitted snapshot remains in your class evidence history.','delete_invalid'=>'That note could not be found.','invalid'=>'Add a title, organization label, and notes.','locked'=>'That submitted version is locked.','submit_invalid'=>'Choose an active class before submitting.']; ob_start(); ?>
        <section id="my-math-notes" class="mb-panel mb-math-notes"><div class="mb-panel-heading"><div><span class="mb-eyebrow">Student-controlled work</span><h2>My Math Notes</h2></div><strong><?php echo count($notes); ?></strong></div><p class="mb-note-privacy"><strong>Private by default.</strong> Teachers see only the version you deliberately submit. A submitted snapshot does not change when you edit later.</p><?php if($notice): ?><div class="mb-note-notice is-<?php echo in_array($notice,['invalid','locked','submit_invalid'],true)?'error':'success'; ?>"><?php echo esc_html($messages[$notice]??'Math notes updated.'); ?></div><?php endif; ?><details class="mb-note-create" <?php echo !$notes?'open':''; ?>><summary>Create a math note</summary><?php echo self::editor([],$classes); ?></details>
        <?php if(!$notes): ?><div class="mb-dashboard-empty"><strong>No structured notes yet.</strong><p>Create private notes organized by topic, unit, standard, I Can statement, week, vocabulary, or your own category.</p></div><?php else: ?><div class="mb-note-list"><?php foreach($notes as $note): $editable=in_array($note['status']??'draft',['draft','revision_requested'],true); ?><article class="mb-note-card is-<?php echo esc_attr($note['color']??'teal'); ?>"><small><?php echo esc_html(ucwords(str_replace('_',' ',$note['status']??'draft'))); ?> · Version <?php echo absint($note['version']??0); ?></small><h3><?php echo esc_html($note['title']); ?></h3><p><strong><?php echo esc_html(ucfirst($note['organization_type'])); ?>:</strong> <?php echo esc_html($note['organization_label']); ?><?php if(!empty($note['subcategory_label'])): ?> → <strong><?php echo esc_html($note['subcategory_type']?:'Subcategory'); ?>:</strong> <?php echo esc_html($note['subcategory_label']); ?><?php endif; ?></p><?php if(!empty($note['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($note['content'])); ?></div><?php endif; ?><?php if(!empty($note['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($note['drawing_data']); ?>" alt="Saved math drawing"><?php endif; ?><?php if(!empty($note['review']['feedback'])): ?><blockquote><strong>Teacher feedback</strong><?php echo wp_kses_post(wpautop($note['review']['feedback'])); ?><?php if(($note['status']??'')==='graded'): ?><p><strong>Grade:</strong> <?php echo esc_html((string)($note['review']['score']??0)); ?><?php echo !empty($note['review']['points_possible'])?' / '.esc_html((string)$note['review']['points_possible']):''; ?> (<?php echo esc_html(ucfirst($note['review']['grade_type']??'points')); ?>)</p><?php endif; ?></blockquote><?php endif; ?><?php if($editable): ?><details><summary>Edit private working copy</summary><?php echo self::editor($note,$classes); ?></details><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Submit this exact version to your teacher? The submitted snapshot will be locked.');"><input type="hidden" name="action" value="mb_student_submit_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_submit_math_note','mb_math_note_submit_nonce'); ?><button type="submit">Submit this version to Teacher</button></form><?php else: ?><p>This submitted snapshot is locked.<?php echo ($note['status']??'')==='graded'?' Your teacher has graded it.':''; ?></p><?php endif; ?><form class="mb-note-delete-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Delete this note from My Math Notes? Previously submitted snapshots will stay in class evidence history.');"><input type="hidden" name="action" value="mb_student_delete_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_delete_math_note','mb_math_note_delete_nonce'); ?><button class="mb-note-delete" type="submit">Delete Note</button></form></article><?php endforeach; ?></div><?php endif; ?></section><?php return ob_get_clean();
    }
    public static function teacher_section($student_id,array $class_ids) {
        $notes=self::submitted_for_student($student_id,$class_ids); $notice=sanitize_key(wp_unslash($_GET['notes_notice']??'')); $messages=['reviewed'=>'Review and grade saved.','canvas_prepared'=>'Canvas submission preview prepared. Nothing was sent.','canvas_grade_sent'=>'The teacher-approved grade and feedback were sent to Canvas SpeedGrader.','canvas_grade_failed'=>'Canvas did not accept the grade. Review the Canvas mapping and synchronization log.','review_denied'=>'You do not have permission to review that note.','canvas_denied'=>'You do not have permission to prepare that note.','canvas_failed'=>'The Canvas preview could not be prepared.']; ob_start(); ?>
        <section id="submitted-math-notes" class="mb-teacher-panel mb-teacher-notes"><div class="mb-teacher-heading"><div><small>Submitted snapshots</small><h2>Math Notes Review</h2><p>Only notes the student deliberately submitted are visible here.</p></div></div><?php if($notice): ?><div class="mb-teacher-review-notice <?php echo in_array($notice,['review_denied','canvas_denied','canvas_failed','canvas_grade_failed'],true)?'is-error':'is-success'; ?>"><?php echo esc_html($messages[$notice]??'Math notes updated.'); ?></div><?php endif; ?><?php if(!$notes): ?><div class="mb-teacher-empty"><strong>No submitted math notes.</strong><p>Private drafts remain private until the student chooses a version to submit.</p></div><?php else: ?><div class="mb-teacher-note-list"><?php foreach(array_reverse($notes) as $note): $s=$note['submitted_snapshot']; $r=(array)($note['review']??[]); ?><article><small><?php echo esc_html(ucwords(str_replace('_',' ',$note['status']))); ?> · Snapshot v<?php echo absint($s['version']); ?></small><h3><?php echo esc_html($s['title']); ?></h3><p><strong><?php echo esc_html(ucfirst($s['organization_type'])); ?>:</strong> <?php echo esc_html($s['organization_label']); ?><?php if(!empty($s['subcategory_label'])): ?> → <strong><?php echo esc_html($s['subcategory_type']?:'Subcategory'); ?>:</strong> <?php echo esc_html($s['subcategory_label']); ?><?php endif; ?></p><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($s['content'])); ?></div><?php if(!empty($s['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($s['drawing_data']); ?>" alt="Submitted math drawing"><?php endif; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="mb_teacher_review_math_note"><input type="hidden" name="student_id" value="<?php echo absint($student_id); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_review_math_note','mb_math_note_review_nonce'); ?><div class="mb-grade-grid"><label>Decision<select name="decision"><?php foreach(['feedback'=>'Feedback','revision_requested'=>'Request revision','graded'=>'Grade'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($r['decision']??'',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>Grade method<select name="grade_type"><?php foreach(['points'=>'Points','percentage'=>'Percentage','completion'=>'Complete / incomplete','rubric'=>'Rubric'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($r['grade_type']??'',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>Score<input type="number" step="0.01" name="score" value="<?php echo esc_attr($r['score']??''); ?>"></label><label>Points possible<input type="number" step="0.01" min="0" name="points_possible" value="<?php echo esc_attr($r['points_possible']??''); ?>"></label><label>Rubric level<input maxlength="100" name="rubric_level" value="<?php echo esc_attr($r['rubric_level']??''); ?>"></label></div><label>Feedback<textarea name="feedback" rows="4"><?php echo esc_textarea(wp_strip_all_tags($r['feedback']??'')); ?></textarea></label><button class="mb-teacher-primary" type="submit">Save Review</button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Prepare this locked snapshot for Canvas preview? Nothing will be sent until you separately approve a grade passback.');"><input type="hidden" name="action" value="mb_teacher_canvas_note_preview"><input type="hidden" name="student_id" value="<?php echo absint($student_id); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_canvas_note_preview','mb_canvas_note_nonce'); ?><button type="submit">Prepare Canvas Preview</button></form><?php echo MathBinder_Canvas_Submission::grade_button($note,$student_id); ?></article><?php endforeach; ?></div><?php endif; ?></section><?php return ob_get_clean();
    }
